def _clear_collection(name):
    col = bpy.data.collections.get(name)
    if col is None:
        return
    for obj in list(col.objects):
        bpy.data.objects.remove(obj, do_unlink=True)
    bpy.data.collections.remove(col)


def _flat_mat(name, rgba):
    mat = bpy.data.materials.get(name)
    if mat is None:
        mat = bpy.data.materials.new(name)
    mat.use_nodes = True
    bsdf = None
    for node in mat.node_tree.nodes:
        if node.type == "BSDF_PRINCIPLED":
            bsdf = node
            break
    if bsdf is None:
        bsdf = mat.node_tree.nodes.new("ShaderNodeBsdfPrincipled")
    color = (float(rgba[0]), float(rgba[1]), float(rgba[2]), 1.0)
    bsdf.inputs["Base Color"].default_value = color
    if "Roughness" in bsdf.inputs:
        bsdf.inputs["Roughness"].default_value = 1.0
    if "Metallic" in bsdf.inputs:
        bsdf.inputs["Metallic"].default_value = 0.0
    if "Alpha" in bsdf.inputs:
        bsdf.inputs["Alpha"].default_value = 1.0
    mat.diffuse_color = color
    return mat


def build():
    _clear_collection(COLLECTION)
    col = bpy.data.collections.new(COLLECTION)
    bpy.context.scene.collection.children.link(col)

    mesh = bpy.data.meshes.new(MESH_NAME)
    mesh.from_pydata(_VERTS, [], _FACES)
    mesh.update()

    obj = bpy.data.objects.new(MESH_NAME, mesh)
    obj.location = (0.0, 0.0, 0.0)
    col.objects.link(obj)

    mesh.materials.clear()
    for name, rgba in _MATERIALS.items():
        mesh.materials.append(_flat_mat(name, rgba))

    for i, poly in enumerate(mesh.polygons):
        poly.use_smooth = False
        if i < len(_MAT_INDEX):
            poly.material_index = int(_MAT_INDEX[i])

    summary = {
        "ok": True,
        "name": obj.name,
        "verts": len(mesh.vertices),
        "faces": len(mesh.polygons),
        "materials": [m.name for m in mesh.materials],
    }
    print(summary)
    return summary


if __name__ == "__main__":
    build()
